response.text:
{
  "modName": "counter_8bit",
  "domain": "general purpose counter",
  "requirements": [
    {
      "id": "REQ-FUNC-001",
      "cat": "Functionality",
      "pri": "Must",
      "desc": "The module shall increment the count on a rising clock edge when 'up' is asserted and decrement when 'down' is asserted.",
      "rat": "[derived from description: When en is high on a rising clock edge, count increments if up else decrements]"
    },
    {
      "id": "REQ-FUNC-002",
      "cat": "Functionality",
      "pri": "Must",
      "desc": "The count value shall saturate at 255 when attempting to increment from 255 and at 0 when attempting to decrement from 0.",
      "rat": "[assumed]"
    },
    {
      "id": "REQ-FUNC-003",
      "cat": "Functionality",
      "pri": "Must",
      "desc": "The reset signal shall asynchronously set the count to zero regardless of current value.",
      "rat": "[domain default]"
    },
    {
      "id": "REQ-TIMING-001",
      "cat": "Timing",
      "pri": "Must",
      "desc": "The counter shall update its value only on a rising edge of the clock when 'en' is high.",
      "rat": "[derived from description: active-high reset and clock edge]"
    },
    {
      "id": "REQ-TIMING-002",
      "cat": "Timing",
      "pri": "Should",
      "desc": "The counter shall maintain its current value when 'en' is low.",
      "rat": "[domain default]"
    },
    {
      "id": "REQ-VERIF-001",
      "cat": "Verification",
      "pri": "Must",
      "desc": "The design shall be synthesizable and free from combinational loops in the update path.",
      "rat": "[derived from description: synchronous active-high reset]"
    },
    {
      "id": "REQ-INTF-001",
      "cat": "Interface",
      "pri": "Must",
      "desc": "The module shall expose a single clock input, a single asynchronous reset, and an 8-bit data output.",
      "rat": "[derived from description: inputs clk, rst, en, output count[7:0]"
    },
    {
      "id": "REQ-INTF-002",
      "cat": "Interface",
      "pri": "Should",
      "desc": "The module shall use a parameterized data width to allow flexibility for different bit-widths.",
      "rat": "[assumed]"
    },
    {
      "id": "REQ-INTF-003",
      "cat": "Interface",
      "pri": "Should",
      "desc": "The module shall include a clear asynchronous reset to ensure predictable initial state.",
      "rat": "[domain default]"
    }
  ],
  "iface": [
    {
      "name": "clk",
      "dir": "input",
      "width": "1",
      "desc": "System clock, rising-edge active"
    },
    {
      "name": "rst_n",
      "dir": "input",
      "width": "1",
      "desc": "Asynchronous active-low reset"
    },
    {
      "name": "count",
      "dir": "output",
      "width": "8",
      "desc": "Current count value, 8-bit wide"
    }
  ],
  "params": [
    {
      "name": "DATA_W",
      "type": "parameter",
      "def": 8,
      "range": "[1:1024]",
      "desc": "Data-path width in bits"
    }
  ]
}
